 17→// copilotEvent is a single line in events.jsonl.
 18→type copilotEvent struct {
 19→	Type      string          `json:"type"`
 20→	Data      json.RawMessage `json:"data"`
 21→	ID        string          `json:"id"`
 22→	Timestamp string          `json:"timestamp"`
 23→	ParentID  string          `json:"parentId"`
 24→}
 25→
 26→const (
 27→	eventTypeUserMessage  = "user.message"
 28→	eventTypeAssistantMsg = "assistant.message"
 29→	eventTypeToolExecDone = "tool.execution_complete"
 30→	eventTypeModelChange  = "session.model_change"
 31→)
 32→
 33→// userMessageData is the data payload for user.message events.
 34→// IMPORTANT: The field is "content", not "message" — verified from real Copilot JSONL.
 35→type userMessageData struct {
 36→	Content string `json:"content"`
 37→}
 38→
 39→type assistantMessageData struct {
 40→	Content string `json:"content"`
 41→}
 42→
 43→// modelChangeData is the data payload for session.model_change events.
 44→// Copilot CLI emits this early in the transcript with the LLM model being used.
 45→type modelChangeData struct {
 46→	NewModel string `json:"newModel"`
 47→}
 48→
 49→type toolExecCompleteData struct {
 50→	ToolCallID    string        `json:"toolCallId"`
 51→	Model         string        `json:"model"`
 52→	ToolTelemetry toolTelemetry `json:"toolTelemetry"`
 53→}
 54→
 55→type toolTelemetry struct {
 56→	Metrics    toolMetrics    `json:"metrics"`
 57→	Properties toolProperties `json:"properties"`
 58→}
 59→
 60→type toolMetrics struct {
 61→	LinesAdded   int `json:"linesAdded"`
 62→	LinesRemoved int `json:"linesRemoved"`
 63→}
