 65→// toolProperties contains string-encoded metadata from tool execution.
 66→// filePaths is a JSON-encoded string array, e.g. "[\"path/to/file.txt\"]".
 67→type toolProperties struct {
 68→	FilePaths string `json:"filePaths"`
 69→}
