 71→// parseEventsFromBytes scans JSONL data and returns all parsed events.
 72→// Malformed lines are silently skipped.
 73→func parseEventsFromBytes(data []byte) ([]copilotEvent, error) {
 74→	return parseEventsFromOffset(data, 0)
 75→}
 76→
 77→// parseEventsFromOffset scans JSONL data and returns events starting after
 78→// the first startOffset lines. Malformed lines are silently skipped.
 79→func parseEventsFromOffset(data []byte, startOffset int) ([]copilotEvent, error) {
 80→	var events []copilotEvent
 81→	scanner := bufio.NewScanner(bytes.NewReader(data))
 82→	scanner.Buffer(make([]byte, 0, bufio.MaxScanTokenSize), 10*1024*1024) // 10 MB max line
 83→	lineNum := 0
 84→
 85→	for scanner.Scan() {
 86→		lineNum++
 87→		if lineNum <= startOffset {
 88→			continue
 89→		}
 90→
 91→		line := scanner.Bytes()
 92→		if len(line) == 0 {
 93→			continue
 94→		}
 95→
 96→		var ev copilotEvent
 97→		if err := json.Unmarshal(line, &ev); err != nil {
 98→			continue // skip malformed lines
 99→		}
100→		events = append(events, ev)
101→	}
102→
103→	if err := scanner.Err(); err != nil {
104→		return events, fmt.Errorf("transcript scanner error: %w", err)
105→	}
106→
107→	return events, nil
108→}
