110→// extractModifiedFilesFromEvents collects file paths from tool.execution_complete
111→// events and returns a deduplicated list.
112→func extractModifiedFilesFromEvents(events []copilotEvent) []string {
113→	seen := make(map[string]bool)
114→	var files []string
115→
116→	for i := range events {
117→		if events[i].Type != eventTypeToolExecDone {
118→			continue
119→		}
120→
121→		var data toolExecCompleteData
122→		if err := json.Unmarshal(events[i].Data, &data); err != nil {
123→			continue
124→		}
125→
126→		// filePaths is a JSON-encoded string array in properties, e.g. "[\"path/to/file\"]"
127→		if data.ToolTelemetry.Properties.FilePaths == "" {
128→			continue
129→		}
130→		var paths []string
131→		if err := json.Unmarshal([]byte(data.ToolTelemetry.Properties.FilePaths), &paths); err != nil {
132→			continue
133→		}
134→		for _, fp := range paths {
135→			if fp != "" && !seen[fp] {
136→				seen[fp] = true
137→				files = append(files, fp)
138→			}
139→		}
140→	}
141→
142→	return files
143→}
