145→// extractPromptsFromEvents collects content from user.message events.
146→func extractPromptsFromEvents(events []copilotEvent) []string {
147→	var prompts []string
148→
149→	for i := range events {
150→		if events[i].Type != eventTypeUserMessage {
151→			continue
152→		}
153→
154→		var data userMessageData
155→		if err := json.Unmarshal(events[i].Data, &data); err != nil {
156→			continue
157→		}
158→
159→		if data.Content != "" {
160→			prompts = append(prompts, data.Content)
161→		}
162→	}
163→
164→	return prompts
165→}
