167→// extractSummaryFromEvents returns the content of the last assistant.message event.
168→func extractSummaryFromEvents(events []copilotEvent) string {
169→	for i := len(events) - 1; i >= 0; i-- {
170→		if events[i].Type != eventTypeAssistantMsg {
171→			continue
172→		}
173→
174→		var data assistantMessageData
175→		if err := json.Unmarshal(events[i].Data, &data); err != nil {
176→			continue
177→		}
178→
179→		if data.Content != "" {
180→			return data.Content
181→		}
182→	}
183→
184→	return ""
185→}
