187→// extractModelFromEvents returns the model from transcript events.
188→// First checks session.model_change events, then falls back to the model field
189→// in tool.execution_complete events (Copilot CLI includes model per tool call).
190→func extractModelFromEvents(events []copilotEvent) string {
191→	// Primary: session.model_change (explicit model declaration)
192→	for i := len(events) - 1; i >= 0; i-- {
193→		if events[i].Type != eventTypeModelChange {
194→			continue
195→		}
196→
197→		var data modelChangeData
198→		if err := json.Unmarshal(events[i].Data, &data); err != nil {
199→			continue
200→		}
201→
202→		if data.NewModel != "" {
203→			return data.NewModel
204→		}
205→	}
206→
207→	// Fallback: tool.execution_complete events include a model field
208→	for i := len(events) - 1; i >= 0; i-- {
209→		if events[i].Type != eventTypeToolExecDone {
210→			continue
211→		}
212→
213→		var data toolExecCompleteData
214→		if err := json.Unmarshal(events[i].Data, &data); err != nil {
215→			continue
216→		}
217→
218→		if data.Model != "" {
219→			return data.Model
220→		}
221→	}
222→
223→	return ""
224→}
