226→// ExtractModelFromTranscript extracts the LLM model name from a Copilot CLI
227→// transcript. It prefers session.model_change events (explicit model
228→// declarations), but falls back to the model field on tool.execution_complete
229→// events for Copilot CLI versions that do not emit session.model_change.
230→// Returns the last observed model, or empty string if unavailable.
231→func ExtractModelFromTranscript(transcriptPath string) string {
232→	if transcriptPath == "" {
233→		return ""
234→	}
235→
236→	data, err := os.ReadFile(transcriptPath) //nolint:gosec // Path derived from agent hook input
237→	if err != nil {
238→		return ""
239→	}
240→
241→	events, err := parseEventsFromBytes(data)
242→	if err != nil {
243→		return ""
244→	}
245→
246→	return extractModelFromEvents(events)
247→}
