249→// GetTranscriptPosition returns the current line count of a Copilot CLI transcript.
250→// Copilot CLI uses JSONL format, so position is the number of lines.
251→// This is a lightweight operation that only counts lines without parsing JSON.
252→// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
253→// Returns 0 if the file doesn't exist or is empty.
254→func (c *CopilotCLIAgent) GetTranscriptPosition(path string) (int, error) {
255→	if path == "" {
256→		return 0, nil
257→	}
258→
259→	file, err := os.Open(path) //nolint:gosec // Path comes from Copilot CLI transcript location
260→	if err != nil {
261→		if os.IsNotExist(err) {
262→			return 0, nil
263→		}
264→		return 0, fmt.Errorf("failed to open transcript file: %w", err)
265→	}
266→	defer file.Close()
267→
268→	reader := bufio.NewReader(file)
269→	lineCount := 0
270→
271→	for {
272→		line, readErr := reader.ReadBytes('\n')
273→		if readErr != nil {
274→			if readErr == io.EOF {
275→				if len(line) > 0 {
276→					lineCount++ // Count final line without trailing newline
277→				}
278→				break
279→			}
280→			return 0, fmt.Errorf("failed to read transcript: %w", readErr)
281→		}
282→		lineCount++
283→	}
284→
285→	return lineCount, nil
286→}
