288→// ExtractModifiedFilesFromOffset extracts files modified since a given line number.
289→// For Copilot CLI (JSONL format), offset is the starting line number.
290→// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
291→// Returns:
292→//   - files: list of file paths modified by Copilot (from tool.execution_complete events)
293→//   - currentPosition: total number of lines in the file
294→//   - error: any error encountered during reading
295→func (c *CopilotCLIAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
296→	if path == "" {
297→		return nil, 0, nil
298→	}
299→
300→	file, openErr := os.Open(path) //nolint:gosec // Path comes from Copilot CLI transcript location
301→	if openErr != nil {
302→		return nil, 0, fmt.Errorf("failed to open transcript file: %w", openErr)
303→	}
304→	defer file.Close()
305→
306→	reader := bufio.NewReader(file)
307→	var events []copilotEvent
308→	lineNum := 0
309→
310→	for {
311→		lineData, readErr := reader.ReadBytes('\n')
312→		if readErr != nil && readErr != io.EOF {
313→			return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
314→		}
315→
316→		if len(lineData) > 0 {
317→			lineNum++
318→			if lineNum > startOffset {
319→				var ev copilotEvent
320→				if parseErr := json.Unmarshal(lineData, &ev); parseErr == nil {
321→					events = append(events, ev)
322→				}
323→				// Skip malformed lines silently
324→			}
325→		}
326→
327→		if readErr == io.EOF {
328→			break
329→		}
330→	}
331→
332→	return extractModifiedFilesFromEvents(events), lineNum, nil
333→}
