335→// ExtractPrompts extracts user prompts from the transcript starting at the given offset.
336→func (c *CopilotCLIAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
337→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
338→	if err != nil {
339→		return nil, fmt.Errorf("failed to read transcript: %w", err)
340→	}
341→
342→	events, err := parseEventsFromOffset(data, fromOffset)
343→	if err != nil {
344→		return nil, fmt.Errorf("failed to parse transcript events: %w", err)
345→	}
346→	return extractPromptsFromEvents(events), nil
347→}
