 60→// GetSessionDir returns the directory where Copilot CLI stores session transcripts.
 61→func (c *CopilotCLIAgent) GetSessionDir(_ string) (string, error) {
 62→	if override := os.Getenv("ENTIRE_TEST_COPILOT_SESSION_DIR"); override != "" {
 63→		return override, nil
 64→	}
 65→
 66→	homeDir, err := os.UserHomeDir()
 67→	if err != nil {
